Appendix A: DSA Cheat Sheet — Patterns and Time Complexities
This is your quick-reference for every Data Structures and Algorithms pattern you will encounter in internship 
interviews. Study this alongside Striver's A2Z sheet. For every problem you solve, map it to one of these  
patterns.
A.1 Sliding Window Pattern
Use when: Finding max/min/sum of a subarray of fixed or variable size. Typical problems: Maximum sum  
subarray of size K, Longest substring without repeating characters, Minimum window substring.
// Template: Fixed window
int left = 0, windowSum = 0, maxSum = 0;
for (int right = 0; right < nums.size(); right++) {
    windowSum += nums[right];
    if (right - left + 1 == k) {
        maxSum = max(maxSum, windowSum);
        windowSum -= nums[left++];
    }
}
// Template: Variable window
int left = 0; unordered_map<char, int> freq;
int maxLen = 0;
for (int right = 0; right < s.size(); right++) {
    freq[s[right]]++;
    while (freq.size() > k) { // condition to shrink
        freq[s[left]]--;
        if (freq[s[left]] == 0) freq.erase(s[left]);
        left++;
    }
    maxLen = max(maxLen, right - left + 1);
}
A.2 Two Pointer Pattern
Use when: Sorted array, finding pairs that sum to target, removing duplicates, palindrome check. Time: O(n). 
Space: O(1).
// Template: Two sum in sorted array
int left = 0, right = nums.size() - 1;
while (left < right) {
    int sum = nums[left] + nums[right];
    if (sum == target) return {left, right};
    else if (sum < target) left++;
    else right--;
}

A.3 Binary Search Pattern
Use when: Sorted array, search space can be halved. Also use for "find minimum value that satisfies a  
condition" problems — binary search on the answer.
// Template: Standard binary search
int left = 0, right = nums.size() - 1;
while (left <= right) {
    int mid = left + (right - left) / 2; // prevents overflow
    if (nums[mid] == target) return mid;
    else if (nums[mid] < target) left = mid + 1;
    else right = mid - 1;
}
// Template: Binary search on answer
int left = min_possible, right = max_possible;
while (left < right) {
    int mid = left + (right - left) / 2;
    if (canAchieve(mid)) right = mid; // search left half
    else left = mid + 1;             // search right half
}
A.4 BFS Pattern — Level Order Traversal
Use for: Shortest path in unweighted graph, level-by-level tree processing, minimum steps problems.
// Graph BFS template
vector<int> visited(n, 0);
queue<int> q;
q.push(start); visited[start] = 1;
while (!q.empty()) {
    int node = q.front(); q.pop();
    for (int neighbour : adj[node]) {
        if (!visited[neighbour]) {
            visited[neighbour] = 1;
            q.push(neighbour);
        }
    }
}
A.5 DFS Pattern — Graph and Tree
Use for: Cycle detection, topological sort, connected components, path finding, tree problems.
// Recursive DFS template
void dfs(int node, vector<vector<int>>& adj, vector<int>& vis) {
    vis[node] = 1;
    for (int neighbour : adj[node]) {

        if (!vis[neighbour]) dfs(neighbour, adj, vis);
    }
}
A.6 Dynamic Programming — 5 Templates
Template 1: 1D DP (Fibonacci-type)
// dp[i] = answer for problem of size i
vector<int> dp(n+1, 0);
dp[0] = base_case_0; dp[1] = base_case_1;
for (int i = 2; i <= n; i++) {
    dp[i] = dp[i-1] + dp[i-2]; // recurrence
}
Template 2: 2D DP (LCS, Edit Distance type)
// dp[i][j] = answer for strings of length i and j
vector<vector<int>> dp(m+1, vector<int>(n+1, 0));
for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
        if (s1[i-1] == s2[j-1]) dp[i][j] = 1 + dp[i-1][j-1];
        else dp[i][j] = max(dp[i-1][j], dp[i][j-1]);
    }
}
