J.3 Alert Manager — Multi-Channel Alert System
"""alert_manager.py — Rule-based alert system with multi-channel dispatch."""
import smtplib, logging, json
from email.mime.text import MIMEText
from email.mime.multipart import MIMEMultipart
from dataclasses import dataclass
from typing import Callable
from datetime import datetime, timedelta
from sensor_manager import Reading
@dataclass
class AlertRule:
    sensor_id: str
    condition: str  # "greater_than" | "less_than" | "equal_to"
    threshold: float
    severity: str   # "info" | "warning" | "critical"
    cooldown_minutes: int = 30  # minimum minutes between alerts
class AlertManager:
    def __init__(self):
        self._rules: list[AlertRule] = []
        self._channels: list[Callable] = []
        self._last_alert: dict[str, datetime] = {}
    def add_rule(self, rule: AlertRule) -> None:
        self._rules.append(rule)
    def add_channel(self, fn: Callable) -> None:
        """Add an alert channel (email, MQTT, webhook, etc.)."""
        self._channels.append(fn)
    def evaluate(self, reading: Reading) -> None:
        """Check reading against all rules, dispatch alerts."""
        for rule in self._rules:
            if rule.sensor_id != reading.sensor_id: continue
            triggered = False
            if rule.condition == "greater_than" and reading.value > rule.threshold: 
triggered = True
            elif rule.condition == "less_than" and reading.value < rule.threshold: 
triggered = True
            if not triggered: continue

            # Check cooldown
            key = f"{rule.sensor_id}_{rule.condition}_{rule.threshold}"
            last = self._last_alert.get(key)
            if last and datetime.utcnow() - last < 
timedelta(minutes=rule.cooldown_minutes):
                continue  # Still in cooldown
            self._last_alert[key] = datetime.utcnow()
            alert = {"sensor_id": reading.sensor_id, "severity": rule.severity,
                     "value": reading.value, "threshold": rule.threshold,
                     "timestamp": reading.timestamp}
            for ch in self._channels:
                try: ch(alert)
                except Exception as e: logging.error(f"Alert channel error: {e}")
def email_channel(smtp_host: str, smtp_port: int, username: str,
                  password: str, to_addr: str) -> Callable:
    """Factory: returns an email alert channel function."""
    def send_email(alert: dict) -> None:
        msg = MIMEMultipart()
        msg["From"] = username
        msg["To"] = to_addr
        msg["Subject"] = f"[{alert['severity'].upper()}] Sensor Alert: 
{alert['sensor_id']}"
        body = f"""
        Sensor Alert Triggered
        Sensor: {alert['sensor_id']}
        Severity: {alert['severity'].upper()}
        Value: {alert['value']}
        Threshold: {alert['threshold']}
        Time: {alert['timestamp']}
        """
        msg.attach(MIMEText(body, "plain"))
        with smtplib.SMTP_SSL(smtp_host, smtp_port) as server:
            server.login(username, password)
            server.sendmail(username, to_addr, msg.as_string())
    return send_email
